import logging
from collections import defaultdict
from typing import Dict, List, Tuple

from ..base import BaseAnalysis
from .loader import Loader
from .trace import LteTtiTraceParser, LteTtiTraceContainer


logger = logging.getLogger(__name__)

NO_VALUE = -1

TIME = 'Time'

CELL_ID_DL = 'ETtiTraceDlParCell_cellId'
CELL_ID_UL = 'ETtiTraceUlParCell_cellId'

CRNTI_DL = 'ETtiTraceDlParUe_cRnti'
CRNTI_UL = 'ETtiTraceUlParUe_cRnti'

SFN_DL = 'ETtiTraceDlParCell_sfn'

ESFN_DL = 'ETtiTraceDlParCell_esfn'
ESFN_UL = 'ETtiTraceUlParCell_esfn'

MIMO_MODE_DL = 'ETtiTraceDlParUe_mimoMode'
TR_NUM_CW1_DL = 'ETtiTraceDlParUe_trNumCW1'
ACK_NACK_DTX_CW1_DL = 'EHarqParDl_ackNackDtxCw1'
ACK_NACK_DTX_CW2_DL = 'EHarqParDl_ackNackDtxCw2'

TR_NUM_CW1_UL = 'ETtiTraceUlParUe_trNumCw1'
ACK_NACK_DTX_CW1_UL = 'EHarqParUl_ackNackDtxCw1'

UL = 'UL'
DL = 'DL'


class LteTtiTraceAnalyzer(object):
    def __init__(self, file_path):
        self.file_path = file_path
        self.loader = Loader()
        self.loader.read_from_file(file_path)

    def get_average_numOfPrbsAlloc(self, direction):
        direction = self._validate_direction(direction)
        trace_container = self._prepare_trace_container_for_given_direction(direction)
        return NumOfPrbsAllocAnalysis(trace_container).get_average(direction)

    def get_maximum_numOfPrbsAlloc(self, direction):
        direction = self._validate_direction(direction)
        trace_container = self._prepare_trace_container_for_given_direction(direction)
        return NumOfPrbsAllocAnalysis(trace_container).get_max(direction)

    def get_average_totalPrbAvail(self, direction, filter_out_broken=True):
        direction = self._validate_direction(direction)
        trace_container = self._prepare_trace_container_for_given_direction(direction, filter_out_broken)
        return TotalPrbAvailAnalysis(trace_container).get_average(direction)

    def get_maximum_totalPrbAvail(self, direction, filter_out_broken=True):
        direction = self._validate_direction(direction)
        trace_container = self._prepare_trace_container_for_given_direction(direction, filter_out_broken)
        return TotalPrbAvailAnalysis(trace_container).get_max(direction)

    def get_average_throughput(self, direction):
        direction = self._validate_direction(direction)
        trace_container = self._prepare_trace_container_for_given_direction(direction, filter_out_broken=False)
        return ThroughputAnalysis(trace_container).get_average_per_ue(direction)

    def _prepare_trace_container_for_given_direction(self, direction, filter_out_broken=True):

        try:
            traces = self.loader.raw_parsed_traces[direction]
        except (AttributeError, IndexError):
            logger.debug('No traces in trace collector?')
            traces = ''

        trace_parser = LteTtiTraceParser(traces)

        trace_container = LteTtiTraceContainer().import_from_trace_parser(
            trace_parser, filter_out_broken=filter_out_broken
        )

        logger.debug('Number of traces after parsing: {}'.format(len(trace_parser.all_traces)))
        logger.debug(
            'Number of traces in trace_container (with filter_out_broken={}): {}'.format(
                filter_out_broken, len(trace_container.traces)
            )
        )

        return trace_container

    @staticmethod
    def _validate_direction(direction):
        if direction.upper() in ('DOWNLINK', 'DL'):
            return DL

        if direction.upper() in ('UPLINK', 'UL'):
            return UL

        raise ValueError('Incorrect indicator of data transfer direction: {}'.format(direction))


class NumOfPrbsAllocAnalysis(BaseAnalysis):
    def __init__(self, trace_container):
        super(NumOfPrbsAllocAnalysis, self).__init__()
        self.trace_container = trace_container

    def get_average(self, direction):
        # type: (str) -> int
        """
        total_numberOfPrsAlloc_for_esfn = [28+28, 32+24, 32+24] -> [56, 56, 56]
        val = rounded_up_mean(total_numberOfPrsAlloc_for_esfn) -> 56
        """
        if not self.trace_container.traces:
            return NO_VALUE

        if direction == DL:
            parameter_per_ue = self._extract_data_for_downlink()
        if direction == UL:
            parameter_per_ue = self._extract_data_for_uplink()

        logger.debug('Calculating average numOfPrbsAlloc for Ues: {}'.format(parameter_per_ue.keys()))
        total_parameter_value_for_esfn_list = [sum(values) for values in zip(*parameter_per_ue.values())]
        return self.calculate_rounded_up_average(total_parameter_value_for_esfn_list)

    def get_max(self, direction):
        # type (str) -> int
        if not self.trace_container.traces:
            return NO_VALUE

        if direction == DL:
            parameter_per_ue = self._extract_data_for_downlink()
        if direction == UL:
            parameter_per_ue = self._extract_data_for_uplink()

        logger.debug('Obtaining maximum numOfPrbsAlloc for Ues: {}'.format(parameter_per_ue.keys()))
        total_parameter_value_for_esfn_list = (sum(values) for values in zip(*parameter_per_ue.values()))

        return int(max(total_parameter_value_for_esfn_list))

    def _extract_data_for_downlink(self):
        # type: () -> Dict
        return self._extract_data('ETtiTraceDlParUe_numberOfPrsAlloc', CRNTI_DL, ESFN_DL)

    def _extract_data_for_uplink(self):
        return self._extract_data('ETtiTraceUlParUe_numberOfPrsAlloc', CRNTI_UL, ESFN_UL)

    def _extract_data(self, actual_par_name, crnti, esfn):
        """The algorithm of extracting data must take into consideration multiple Ues.

        For example, for traces
        +-----------------------------+----------------------------+------------------------------------+
        |    ETtiTraceDlParCell_esfn  |    ETtiTraceDlParUe_cRnti  | ETtiTraceDlParUe_numberOfPrsAlloc  |
        +=============================+============================+====================================+
        | 2                           | 19799                      | 28                                 |
        +-----------------------------+----------------------------+------------------------------------+
        | 2                           | 42621                      | 28                                 |
        +-----------------------------+----------------------------+------------------------------------+
        | 3                           | 19799                      | 32                                 |
        +-----------------------------+----------------------------+------------------------------------+
        | 3                           | 42621                      | 24                                 |
        +-----------------------------+----------------------------+------------------------------------+
        | 4                           | 19799                      | 32                                 |
        +-----------------------------+----------------------------+------------------------------------+
        | 4                           | 42621                      | 24                                 |
        +-----------------------------+----------------------------+------------------------------------+

        there are two Ues: 19799 and 42621. First, one needs to calculate the total numberOfPrsAlloc for
        each esfn,

        total_numberOfPrsAlloc_for_esfn = [28+28, 32+24, 32+24] -> [56, 56, 56]
        val = rounded_up_mean(total_numberOfPrsAlloc_for_esfn) -> 56
        """
        traces = self.trace_container.traces

        max_ues = 10

        # if actual_par_name not in self.trace_reader.reader.fieldnames:
        #     logger.info('{} column not found in trace data'.format(actual_par_name))
        #     return NO_VALUE

        # get the number of Ues
        ue_ids = {trace.get(crnti) for trace in self.trace_container[0:max_ues]}
        n_of_ues = len(ue_ids)

        # verify if there's no offset, e.g., if there are 3 Ues, the first three esfn are identical!
        # and set offset to meet this condition
        offset = 0
        esfn = [trace.get(esfn) for trace in traces[offset:n_of_ues]]
        while not (len(esfn) == n_of_ues and len(set(esfn)) == 1):
            offset += 1
            esfn = [trace.get(esfn) for trace in traces[offset:n_of_ues]]

            if offset > n_of_ues:
                return {'-1': NO_VALUE}

        # split the value per Ue
        parameter_per_ue = defaultdict(list)
        for trace in traces[offset:]:
            ue_id = trace.get(crnti)
            value = trace.get(actual_par_name)
            parameter_per_ue[ue_id].append(int(value))

        return parameter_per_ue


class TotalPrbAvailAnalysis(BaseAnalysis):

    def __init__(self, trace_container):
        super(TotalPrbAvailAnalysis, self).__init__()
        self.trace_container = trace_container

    def get_average(self, direction):
        # type: (str) -> int
        if not self.trace_container.traces:
            return NO_VALUE

        if direction == UL:
            all_values = self._extract_data_for_uplink()
        if direction == DL:
            all_values = self._extract_data_for_downlink()

        return self.calculate_rounded_up_average(all_values)

    def get_max(self, direction):
        # type: (str) -> int
        if not self.trace_container.traces:
            return NO_VALUE

        if direction == UL:
            all_values = self._extract_data_for_uplink()
        if direction == DL:
            all_values = self._extract_data_for_downlink()

        return int(max(all_values))

    def _extract_data_for_uplink(self):
        """
        the filtering for `all_values` results from VBA macro:

            If InStr(sheetName, "Uplink") <> 0 And (InStr(OneTextLine, ",PDCCH for DL,") <> 0 Or InStr(OneTextLine, ",CSS: PDCCH for DL") <> 0) Then
                'do nothing
            Else

        (not all traces for uplink are loaded into a spreadsheet, hence they will not be taken into consideration here either)

        """
        traces = self.trace_container.traces

        actual_par_name = 'ETtiTraceUlParCell_totalPrbAvail'

        # if actual_par_name not in self.header:
        #     logger.info('{} column not found in trace data'.format(actual_par_name))
        #     return NO_VALUE
        filtered_traces = (trace for trace in traces if 'PDCCH for DL' not in trace._fields.values())
        all_values = [int(trace.get(actual_par_name)) for trace in filtered_traces]
        return all_values

    def _extract_data_for_downlink(self):
        """
        """
        traces = self.trace_container.traces

        actual_par_name = 'ETtiTraceDlParCell_totalPrbAvail'

        filtered_traces = traces  # TODO DO WE NEEED FILTERING HERE?
        all_values = [int(trace.get(actual_par_name)) for trace in filtered_traces]
        return all_values


class ThroughputAnalysis(BaseAnalysis):
    """
    traces_for_analysis are all traces minus a head and a tail
    meaning that the first analyzed trace starts with SFN (esfn) == 0,
    and the last trace has SFN (esfn) == 9

    For each FN (sfn) there should be 10 SFNs (esfn) - so this is the expected number of traces
    in this slice after cutting off head and tail.

    In practice, there will be even less valid traces for two reasons: there happen to be broken traces
    (with crnti == '-'), and at some SFNs (esfns) Ues are not allocated. Hence the 'proportion' factor is calculated.

    """
    def __init__(self, trace_container):
        super(ThroughputAnalysis, self).__init__()
        self.trace_container = trace_container
        self._traces_for_analysis = []

    @property
    def traces_for_analysis(self):
        if self._traces_for_analysis:
            return self._traces_for_analysis

        traces = self.trace_container.traces

        # first, determine offset (we want traces to start with the first trace with SFN == 0)
        head_offset = 0
        while True:
            if traces[head_offset].get(ESFN_DL) == '0':
                break
            head_offset += 1

        # logically, we may also want traces to end with the last SFN == 9
        tail_offset = -1
        while True:
            if traces[tail_offset].get(ESFN_DL) == '9':
                break
            tail_offset -= 1

        tail_offset += 1
        traces_slice = slice(head_offset, tail_offset or None)

        self._traces_for_analysis = traces[traces_slice]
        return self._traces_for_analysis

    def get_average_per_ue(self, direction):
        # type: (str) -> Dict
        if not self.trace_container.traces:
            return {'-1': NO_VALUE}

        if direction == UL:
            logger.info('LTE throughput analysis not available for UL')
            return {'-1': NO_VALUE}

        ues = self.trace_container.get_list_of_crntis()

        tput_over_time_per_ue = {}
        for ue in ues:
            tput_over_time_per_ue[ue] = self._extract_data_for_downlink_for_ue(ue)

        average_tput = {}
        for ue, (proportion, tput_values) in tput_over_time_per_ue.items():
            if tput_values:
                average_tput[ue] = int(proportion * 1000 * self.calculate_rounded_average(tput_values, precision=4))

        return average_tput

    @staticmethod
    def _how_many_sfns(traces):
        sfn_counter = 0
        current_sfn = -1
        for trace in traces:
            sfn = trace.get(SFN_DL)
            if sfn != current_sfn:
                sfn_counter += 1
                current_sfn = sfn

        return sfn_counter

    def _extract_data_for_downlink_for_ue(self, ue):
        # type: (str) -> Tuple[float, List[int]]
        """
        """
        actual_par_name = 'ETtiTraceDlParUe_averTbSize'

        non_broken_traces_for_ue = (trace for trace in self.traces_for_analysis
                                    if not trace.broken and trace.get(CRNTI_DL) == ue
                                    )

        sfn_counter = self._how_many_sfns(self.traces_for_analysis)

        tput_values = [int(trace.get(actual_par_name)) for trace in non_broken_traces_for_ue]

        expected_number_of_traces = sfn_counter * 10  # there are supposed to be 10 esfns in an sfn

        proportion = len(tput_values) / float(expected_number_of_traces)

        return proportion, tput_values
